.btn-dew{position: relative; padding: 0.65rem 1.75rem; background: var(--dew-glass); border: 1px solid var(--dew-border); border-radius: 100px; color: var(--cream-light); font-family: var(--font-body); font-size: 0.72rem; letter-spacing: 0.18em; text-transform: uppercase; cursor: none; backdrop-filter: blur(20px) saturate(1.3); overflow: hidden; transition: 0.45s cubic-bezier(0.16, 1, 0.3, 1); font-weight: 400;}
.btn-dew::before{content: ""; position: absolute; top: 0px; left: 0px; right: 0px; height: 50%; background: linear-gradient(180deg, var(--dew-shine) 0%, transparent 100%); border-radius: 100px 100px 0px 0px; pointer-events: none;}
.btn-dew::after{content: ""; position: absolute; inset: 0px; background: radial-gradient(circle at var(--mx, 50%) var(--my, 50%),
    oklch(92% 0.12 85 / 0.25) 0%, transparent 55%); opacity: 0; transition: opacity 0.35s; border-radius: 100px;}
.btn-dew:hover::after{opacity: 1;}
.btn-dew:hover{border-color: oklch(0.88 0.14 85 / 0.4); box-shadow: oklch(0.75 0.16 80 / 0.2) 0px 8px 40px, oklch(0.92 0.12 85 / 0.08) 0px 0px 20px inset;}
.btn-dew-gold{background: oklch(0.75 0.16 80 / 0.2); border-color: oklch(0.88 0.14 85 / 0.35); color: var(--gold-bright);}
.btn-dew-gold:hover{background: oklch(0.75 0.16 80 / 0.32); box-shadow: oklch(0.75 0.16 80 / 0.3) 0px 8px 50px, oklch(0.92 0.12 85 / 0.12) 0px 0px 30px inset;}
.hero{min-height: 100vh; display: flex; flex-direction: column; justify-content: center; padding-top: clamp(6rem, 14vh, 10rem); padding-bottom: 4rem; position: relative;}
.hero-flow{display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center;}
.hero-text-column{position: relative;}
.eyebrow{display: inline-flex; align-items: center; gap: 0.75rem; margin-bottom: 2rem; opacity: 0; animation: 1s cubic-bezier(0.16, 1, 0.3, 1) 0.3s 1 normal forwards running petal-unfold;}
.eyebrow-leaf{width: 24px; height: 1px; background: linear-gradient(90deg, var(--gold-warm), transparent);}
.eyebrow-text{font-size: 0.65rem; letter-spacing: 0.4em; text-transform: uppercase; color: var(--gold-mid); font-weight: 500;}
.hero-title{font-family: var(--font-display); font-size: clamp(3.2rem, 7vw, 6.5rem); font-weight: 300; letter-spacing: -0.025em; line-height: 0.92; margin-bottom: 1.75rem; color: var(--cream-light);}
.hero-title-line{display: block; overflow: hidden;}
.hero-title-line span{display: inline-block; opacity: 0; transform: translateY(110%) rotate(2deg); animation: 1.1s cubic-bezier(0.16, 1, 0.3, 1) 0s 1 normal forwards running petal-rise;}
.hero-title-line:nth-child(1) span{animation-delay: 0.5s;}
.hero-title-line:nth-child(2) span{animation-delay: 0.68s;}
.hero-title-line:nth-child(3) span{animation-delay: 0.86s;}
.hero-title .italic{font-style: italic; color: var(--gold-bright); font-weight: 300;}
.hero-subtitle{font-size: clamp(0.85rem, 1.1vw, 1rem); color: oklch(0.88 0.05 90 / 0.65); line-height: 1.75; max-width: 42ch; margin-bottom: 2.5rem; font-weight: 300; opacity: 0; animation: 0.9s cubic-bezier(0.16, 1, 0.3, 1) 1.2s 1 normal forwards running petal-unfold;}
.hero-actions{display: flex; gap: 1rem; align-items: center; opacity: 0; animation: 0.9s cubic-bezier(0.16, 1, 0.3, 1) 1.4s 1 normal forwards running petal-unfold;}
.lunar-portal-wrap{position: relative; display: flex; align-items: center; justify-content: center; opacity: 0; animation: 1.2s cubic-bezier(0.16, 1, 0.3, 1) 0.6s 1 normal forwards running petal-unfold;}
.lunar-portal{position: relative; width: clamp(300px, 42vw, 560px); aspect-ratio: 4 / 5; border-radius: 60% 40% 55% 45% / 50% 55% 45% 50%; overflow: hidden; mask-image: radial-gradient(85% 88%, black 40%, transparent 100%); animation: 20s ease-in-out 0s infinite normal none running portal-morph;}
.lunar-portal-video{width: 100%; height: 100%; object-fit: cover; filter: saturate(1.3) brightness(0.9) sepia(0.2);}
.lunar-portal-fallback{position: absolute; inset: 0px; background: radial-gradient(60% 70% at 50% 30%, oklch(0.88 0.14 85 / 0.8) 0%, oklch(0.75 0.16 80 / 0.5) 30%, transparent 70%), radial-gradient(80% 60% at 30% 80%, oklch(0.52 0.15 72 / 0.8) 0%, oklch(0.38 0.12 68 / 0.6) 50%, transparent 80%), radial-gradient(50% 50% at 70% 60%, oklch(0.72 0.14 145 / 0.3) 0%, transparent 60%), oklch(0.28 0.08 68); animation: 10s ease-in-out 0s infinite normal none running harvest-shimmer;}
.lunar-portal-glow{position: absolute; inset: -20%; border-radius: inherit; background: radial-gradient(oklch(0.88 0.14 85 / 0.25) 0%, oklch(0.75 0.16 80 / 0.1) 50%, transparent 80%); filter: blur(40px); z-index: -1; animation: 20s ease-in-out 0s infinite normal none running portal-morph;}
.portal-overlay{position: absolute; inset: 0px; background: radial-gradient(40% 40% at 50% 25%, oklch(0.96 0.05 90 / 0.15) 0%, transparent 70%), linear-gradient(transparent 50%, oklch(0.18 0.05 65 / 0.6) 100%); pointer-events: none;}
.moon-badge{position: absolute; top: 12%; right: -5%; width: 80px; height: 80px; background: oklch(0.88 0.03 100 / 0.15); backdrop-filter: blur(20px); border: 1px solid oklch(0.88 0.03 100 / 0.25); border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-direction: column; gap: 0.2rem; animation: 6s ease-in-out 0s infinite normal none running badge-float;}
.moon-badge-val{font-family: var(--font-display); font-size: 1.1rem; font-weight: 600; color: var(--moon-silver); letter-spacing: -0.03em; line-height: 1;}
.moon-badge-label{font-size: 0.5rem; letter-spacing: 0.2em; text-transform: uppercase; color: oklch(0.88 0.03 100 / 0.7); text-align: center;}
.stats-river{display: flex; gap: 0px; margin-top: clamp(3rem, 8vh, 6rem); position: relative;}
.stats-river::before{content: ""; position: absolute; top: 0px; left: 0px; right: 0px; height: 1px; background: linear-gradient(90deg, transparent, oklch(0.88 0.14 85 / 0.3) 20%, oklch(0.88 0.14 85 / 0.15) 80%, transparent);}
.stat-pod{flex: 1 1 0%; padding: 2rem 2rem 2rem 0px; border-right: 1px solid oklch(0.88 0.14 85 / 0.08); margin-right: 2rem;}
.stat-pod:last-child{border-right-width: medium; border-right-style: none; border-right-color: currentcolor;}
.stat-num{font-family: var(--font-display); font-size: clamp(2rem, 3.5vw, 3rem); font-weight: 300; letter-spacing: -0.05em; color: var(--cream-light); line-height: 1; margin-bottom: 0.4rem;}
.stat-num .unit{font-size: 0.5em; color: var(--gold-mid); vertical-align: super; font-weight: 400;}
.stat-label{font-size: 0.65rem; letter-spacing: 0.2em; text-transform: uppercase; color: oklch(0.75 0.05 85 / 0.55); line-height: 1.5;}
.wind-sway{display: inline-block; animation: 8s ease-in-out 0s infinite normal none running wind-sway;}
@media (max-width: 900px){.hero-flow{grid-template-columns: 1fr; gap: 3rem;}}

.btn-dew{position: relative; padding: 0.65rem 1.75rem; background: var(--dew-glass); border: 1px solid var(--dew-border); border-radius: 100px; color: var(--cream-light); font-family: var(--font-body); font-size: 0.72rem; letter-spacing: 0.18em; text-transform: uppercase; cursor: none; backdrop-filter: blur(20px) saturate(1.3); overflow: hidden; transition: 0.45s cubic-bezier(0.16, 1, 0.3, 1); font-weight: 400;}
.btn-dew::before{content: ""; position: absolute; top: 0px; left: 0px; right: 0px; height: 50%; background: linear-gradient(180deg, var(--dew-shine) 0%, transparent 100%); border-radius: 100px 100px 0px 0px; pointer-events: none;}
.btn-dew::after{content: ""; position: absolute; inset: 0px; background: radial-gradient(circle at var(--mx, 50%) var(--my, 50%),
    oklch(92% 0.12 85 / 0.25) 0%, transparent 55%); opacity: 0; transition: opacity 0.35s; border-radius: 100px;}
.btn-dew:hover::after{opacity: 1;}
.btn-dew:hover{border-color: oklch(0.88 0.14 85 / 0.4); box-shadow: oklch(0.75 0.16 80 / 0.2) 0px 8px 40px, oklch(0.92 0.12 85 / 0.08) 0px 0px 20px inset;}
.rhizo-section{padding: clamp(5rem, 12vh, 10rem) 0px; position: relative;}
.rhizo-flow{display: flex; flex-direction: column; gap: clamp(5rem, 10vh, 8rem);}
.rhizo-row{display: grid; align-items: start; position: relative;}
.rhizo-row.left{grid-template-columns: 1fr 1.4fr; gap: 5rem;}
.rhizo-row.right{grid-template-columns: 1.4fr 1fr; gap: 5rem;}
.rhizo-row.center{grid-template-columns: 1fr 1fr 1fr; gap: 3rem; align-items: center;}
.section-eyebrow{display: flex; align-items: center; gap: 0.75rem; margin-bottom: 1.25rem;}
.leaf-stem{width: 30px; height: 1px; background: linear-gradient(90deg, var(--gold-warm), transparent);}
.section-tag{font-size: 0.62rem; letter-spacing: 0.38em; text-transform: uppercase; color: var(--gold-mid); font-weight: 500;}
.section-title{font-family: var(--font-display); font-size: clamp(2rem, 3.5vw, 3.2rem); font-weight: 300; letter-spacing: -0.02em; line-height: 1.1; color: var(--cream-light); margin-bottom: 1.25rem;}
.section-title .italic{font-style: italic; color: var(--gold-bright);}
.section-body{font-size: 0.875rem; color: oklch(0.88 0.05 90 / 0.6); line-height: 1.8; font-weight: 300; max-width: 46ch;}
.amber-leak{width: 100%; height: 1px; background: radial-gradient(60% 100% at 30% 50%, oklch(0.88 0.14 85 / 0.35) 0%, oklch(0.75 0.16 80 / 0.15) 50%, transparent 100%); margin: 0.5rem 0px; position: relative;}
.amber-leak::after{content: ""; position: absolute; top: 0px; left: 0px; width: 40%; height: 100%; background: linear-gradient(90deg, oklch(0.88 0.14 85 / 0.5), transparent); filter: blur(4px);}
.bio-card{position: relative; padding: 2rem 2rem 2rem 2.25rem; background: oklch(0.28 0.07 70 / 0.5); border: 1px solid oklch(0.88 0.14 85 / 0.1); border-radius: 24px 8px; overflow: hidden; backdrop-filter: blur(40px) saturate(1.3); transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.5s; cursor: none;}
.bio-card::before{content: ""; position: absolute; top: 0px; left: 0px; right: 0px; height: 1px; background: linear-gradient(90deg, transparent, oklch(0.92 0.12 85 / 0.25) 40%, transparent);}
.bio-card::after{content: ""; position: absolute; top: 0px; left: 0px; width: 3px; height: 40%; background: linear-gradient(180deg, var(--gold-warm), transparent); border-radius: 0px 0px 3px 3px;}
.bio-card:hover{transform: translateY(-6px) rotate(-0.5deg); box-shadow: oklch(0.15 0.06 65 / 0.5) 0px 40px 80px, oklch(0.88 0.14 85 / 0.12) 0px 0px 0px 1px;}
.bio-card-glow{position: absolute; inset: 0px; background: radial-gradient(circle at var(--mx, 50%) var(--my, 50%),
    oklch(92% 0.12 85 / 0.08) 0%, transparent 55%); opacity: 0; transition: opacity 0.4s; pointer-events: none;}
.bio-card:hover .bio-card-glow{opacity: 1;}
.bio-card-icon{width: 44px; height: 44px; border-radius: 12px; background: oklch(0.88 0.14 85 / 0.1); border: 1px solid oklch(0.88 0.14 85 / 0.15); display: flex; align-items: center; justify-content: center; margin-bottom: 1.25rem; font-size: 1.2rem; color: var(--gold-bright);}
.bio-card-title{font-family: var(--font-display); font-size: 1.2rem; font-weight: 400; letter-spacing: -0.01em; color: var(--cream-light); margin-bottom: 0.6rem; line-height: 1.25;}
.bio-card-text{font-size: 0.78rem; color: oklch(0.8 0.05 85 / 0.55); line-height: 1.75; font-weight: 300;}
.metric-row{display: flex; align-items: center; gap: 0.75rem; margin-top: 1.25rem; padding-top: 1.25rem; border-top: 1px solid oklch(0.88 0.14 85 / 0.08);}
.metric-val{font-family: var(--font-display); font-size: 1.6rem; font-weight: 300; letter-spacing: -0.04em; color: var(--gold-bright); line-height: 1;}
.metric-label{font-size: 0.65rem; letter-spacing: 0.18em; text-transform: uppercase; color: oklch(0.75 0.05 85 / 0.5); line-height: 1.4;}
.progress-vine{width: 100%; height: 2px; background: oklch(0.4 0.08 70 / 0.4); border-radius: 1px; margin-top: 0.5rem; overflow: hidden; position: relative;}
.progress-vine-fill{height: 100%; background: linear-gradient(90deg, var(--gold-warm), var(--gold-bright)); border-radius: 1px; transition: width 1.8s cubic-bezier(0.16, 1, 0.3, 1); position: relative;}
.progress-vine-fill::after{content: ""; position: absolute; right: 0px; top: 50%; transform: translateY(-50%); width: 6px; height: 6px; border-radius: 50%; background: var(--gold-bright); box-shadow: 0 0 8px var(--gold-warm);}
.circadian-display{background: oklch(0.22 0.06 65 / 0.7); border: 1px solid oklch(0.88 0.14 85 / 0.12); border-radius: 28px; padding: 2.5rem; position: relative; overflow: hidden; backdrop-filter: blur(60px);}
.circadian-ring{position: relative; width: 160px; height: 160px; margin: 0px auto 2rem;}
.circadian-ring svg{width: 100%; height: 100%; transform: rotate(-90deg); filter: drop-shadow(oklch(0.88 0.14 85 / 0.4) 0px 0px 12px);}
.circadian-ring-center{position: absolute; inset: 0px; display: flex; align-items: center; justify-content: center; flex-direction: column; gap: 0.25rem;}
.circadian-ring-val{font-family: var(--font-display); font-size: 2.2rem; font-weight: 300; letter-spacing: -0.04em; color: var(--gold-bright); line-height: 1;}
.circadian-ring-label{font-size: 0.6rem; letter-spacing: 0.3em; text-transform: uppercase; color: oklch(0.75 0.05 85 / 0.5);}
.circadian-phases{display: grid; grid-template-columns: 1fr 1fr; gap: 0.75rem;}
.phase-item{padding: 0.75rem; background: oklch(0.28 0.07 70 / 0.5); border-radius: 12px; border: 1px solid oklch(0.88 0.14 85 / 0.08);}
.phase-dot{width: 6px; height: 6px; border-radius: 50%; display: inline-block; margin-right: 0.4rem; vertical-align: middle;}
.phase-name{font-size: 0.68rem; letter-spacing: 0.12em; text-transform: uppercase; color: oklch(0.75 0.05 85 / 0.6); margin-bottom: 0.3rem;}
.phase-val{font-family: var(--font-display); font-size: 1rem; font-weight: 400; color: var(--cream-light); letter-spacing: -0.02em;}
.scrubber-viz{position: relative; padding: 2rem; background: oklch(0.25 0.07 70 / 0.6); border: 1px solid oklch(0.88 0.14 85 / 0.1); border-radius: 8px 28px; backdrop-filter: blur(50px); overflow: hidden;}
.scrubber-title{font-family: var(--font-display); font-size: 1.5rem; font-weight: 300; letter-spacing: -0.02em; color: var(--cream-light); margin-bottom: 0.4rem;}
.scrubber-sub{font-size: 0.7rem; letter-spacing: 0.18em; text-transform: uppercase; color: var(--gold-mid); margin-bottom: 1.5rem;}
.scrubber-bars{display: flex; align-items: flex-end; gap: 4px; height: 80px;}
.scrubber-bar{flex: 1 1 0%; border-radius: 3px 3px 0px 0px; background: linear-gradient(180deg, var(--gold-bright), var(--gold-warm)); animation: 3s ease-in-out 0s infinite normal none running scrub-pulse; transform-origin: center bottom; opacity: 0.7;}
.regolith-stream{display: flex; flex-direction: column; gap: 0.75rem;}
.regolith-item{display: flex; align-items: center; gap: 1rem; padding: 1rem 1.25rem; background: oklch(0.28 0.07 70 / 0.4); border: 1px solid oklch(0.88 0.14 85 / 0.08); border-radius: 100px; backdrop-filter: blur(30px); transition: 0.4s cubic-bezier(0.16, 1, 0.3, 1); cursor: none;}
.regolith-item:hover{background: oklch(0.32 0.09 72 / 0.6); border-color: oklch(0.88 0.14 85 / 0.2); transform: translateX(8px);}
.regolith-icon{width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 1rem; flex-shrink: 0;}
.ri-gold{background: oklch(0.88 0.14 85 / 0.12); color: var(--gold-bright);}
.ri-green{background: oklch(0.72 0.14 145 / 0.12); color: var(--leaf-green);}
.ri-silver{background: oklch(0.88 0.03 100 / 0.1); color: var(--moon-silver);}
.regolith-name{font-size: 0.82rem; font-weight: 400; color: var(--cream-light); flex: 1 1 0%;}
.regolith-pct{font-family: var(--font-display); font-size: 1rem; font-weight: 400; color: var(--gold-mid); letter-spacing: -0.02em;}
.bloom-reveal{opacity: 0; transform: translateY(28px) scale(0.98); transition: opacity 0.9s cubic-bezier(0.16, 1, 0.3, 1), transform 0.9s cubic-bezier(0.16, 1, 0.3, 1);}
.bloom-reveal.bloomed{opacity: 1; transform: none;}
.bloom-d1{transition-delay: 0.1s;}
.bloom-d2{transition-delay: 0.2s;}
@media (max-width: 900px){.rhizo-row.left, .rhizo-row.right{grid-template-columns: 1fr; gap: 2rem;}}
@media (max-width: 900px){.rhizo-row.center{grid-template-columns: 1fr;}}

